mapper.select:
SELECT lr.id, lr.flow_no AS flowNo, lr.leave_type AS leaveType, lr.start_date AS startDate, lr.end_date AS endDate, lr.leave_days AS leaveDays, lr.reason, lr.status, lr.submitted_at AS submittedAt, lr.approver_id AS approverId, lr.approved_at AS approvedAt, lr.approve_remark AS approveRemark, lr.user_id AS userId, u.name AS userName, u.employee_no AS employeeNo, u.avatar_url AS avatarUrl, d.name AS department FROM leave_request lr JOIN sys_user u ON u.id = lr.user_id LEFT JOIN department d ON d.id = u.department_id WHERE lr.deleted_at IS NULL AND lr.status = #{status}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR lr.leave_type LIKE CONCAT('%', #{keyword}, '%') OR lr.flow_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY lr.submitted_at DESC, lr.id DESC
